<?php

declare(strict_types=1);

use Illuminate\Foundation\Testing\RefreshDatabase;
use Inertia\Testing\AssertableInertia;
use Modules\Ticket\Models\Ticket;
use Yuan\AdminCore\Audit\ImmutableActivity;
use Yuan\AdminCore\Testing\ModuleAssertions;

use function Pest\Laravel\delete;
use function Pest\Laravel\get;
use function Pest\Laravel\post;
use function Pest\Laravel\put;

// Tiket (generated by make:module): the AGENTS §8 cases for each declared action.

uses(RefreshDatabase::class);

/**
 * A valid form submission, as the create page sends it.
 *
 * @param  array<string, mixed>  $overrides
 * @return array<string, mixed>
 */
function ticketInput(array $overrides = []): array
{
    return [
        'number' => 'Contoh Number',
        'subject' => 'Contoh Subject',
        'requester' => 'Contoh Requester',
        'message' => 'Catatan contoh',
        'priority' => 'rendah',
        'status' => 'baru',
        'assignee' => 'Contoh Assignee',
        ...$overrides,
    ];
}

it('redirects guests to login', function (): void {
    $ticket = Ticket::factory()->create();

    ModuleAssertions::assertGuestRedirected('get', '/admin/tickets');
    ModuleAssertions::assertGuestRedirected('get', "/admin/tickets/{$ticket->id}");
    ModuleAssertions::assertGuestRedirected('get', '/admin/tickets/create');
    ModuleAssertions::assertGuestRedirected('post', '/admin/tickets');
    ModuleAssertions::assertGuestRedirected('get', "/admin/tickets/{$ticket->id}/edit");
    ModuleAssertions::assertGuestRedirected('put', "/admin/tickets/{$ticket->id}");
    ModuleAssertions::assertGuestRedirected('delete', "/admin/tickets/{$ticket->id}");
    ModuleAssertions::assertGuestRedirected('delete', '/admin/tickets');
});

it('needs the permission of each action', function (): void {
    $ticket = Ticket::factory()->create();

    ModuleAssertions::assertForbiddenWithout('tickets.view', 'get', '/admin/tickets');
    ModuleAssertions::assertForbiddenWithout('tickets.view', 'get', "/admin/tickets/{$ticket->id}");
    ModuleAssertions::assertForbiddenWithout('tickets.create', 'get', '/admin/tickets/create');
    ModuleAssertions::assertForbiddenWithout('tickets.create', 'post', '/admin/tickets', ticketInput());
    ModuleAssertions::assertForbiddenWithout('tickets.edit', 'get', "/admin/tickets/{$ticket->id}/edit");
    ModuleAssertions::assertForbiddenWithout('tickets.edit', 'put', "/admin/tickets/{$ticket->id}", ticketInput(['lock_version' => $ticket->lock_version]));
    ModuleAssertions::assertForbiddenWithout('tickets.delete', 'delete', "/admin/tickets/{$ticket->id}");
    ModuleAssertions::assertForbiddenWithout('tickets.delete', 'delete', '/admin/tickets', ['ids' => [$ticket->id]]);

    expect($ticket->fresh()?->trashed())->toBeFalse();
});

it('lists and shows tiket records', function (): void {
    $ticket = Ticket::factory()->create();
    ModuleAssertions::actingAsLevelWith(['tickets.view']);

    AssertableInertia::fromTestResponse(get('/admin/tickets')->assertOk())
        ->component('Ticket::Index')
        ->count('tickets.items', 1)
        ->where('tickets.items.0.id', $ticket->id);

    AssertableInertia::fromTestResponse(get("/admin/tickets/{$ticket->id}")->assertOk())
        ->component('Ticket::Show')
        ->where('ticket.id', $ticket->id)
        ->where('breadcrumbs.items.1.label', $ticket->auditLabel());
});

it('rejects a sort the list does not allow', function (): void {
    ModuleAssertions::actingAsLevelWith(['tickets.view']);

    get('/admin/tickets?sort=lock_version')->assertStatus(400);
});

it('scopes every tiket query to the signed-in user', function (): void {
    $ticket = Ticket::factory()->create();
    ModuleAssertions::actingAsLevelWith(['tickets.view', 'tickets.create', 'tickets.edit', 'tickets.delete']);

    ModuleAssertions::assertScopedToUser(Ticket::class, 'get', '/admin/tickets');
    ModuleAssertions::assertScopedToUser(Ticket::class, 'get', "/admin/tickets/{$ticket->id}");
    ModuleAssertions::assertScopedToUser(Ticket::class, 'get', "/admin/tickets/{$ticket->id}/edit");
    ModuleAssertions::assertScopedToUser(Ticket::class, 'put', "/admin/tickets/{$ticket->id}", ticketInput(['lock_version' => $ticket->lock_version]));
    ModuleAssertions::assertScopedToUser(Ticket::class, 'delete', '/admin/tickets', ['ids' => [$ticket->id]]);
    ModuleAssertions::assertScopedToUser(Ticket::class, 'delete', "/admin/tickets/{$ticket->id}");
});

it('creates a tiket and audits it', function (): void {
    ModuleAssertions::actingAsLevelWith(['tickets.view', 'tickets.create']);

    post('/admin/tickets', ticketInput())->assertSessionHasNoErrors()->assertRedirect();

    $ticket = Ticket::query()->sole();
    ModuleAssertions::assertAudited($ticket, 'created');
});

it('rejects a tiket without its required fields', function (): void {
    ModuleAssertions::actingAsLevelWith(['tickets.view', 'tickets.create']);

    post('/admin/tickets', [])->assertSessionHasErrors(['number', 'subject', 'requester', 'message', 'priority', 'status']);

    expect(Ticket::query()->count())->toBe(0);
});

it('updates a tiket and audits the change', function (): void {
    $ticket = Ticket::factory()->create();
    ModuleAssertions::actingAsLevelWith(['tickets.view', 'tickets.edit']);

    AssertableInertia::fromTestResponse(get("/admin/tickets/{$ticket->id}/edit")->assertOk())
        ->component('Ticket::Edit')
        ->where('ticket.lock_version', 0);

    put("/admin/tickets/{$ticket->id}", ticketInput(['lock_version' => $ticket->lock_version]))
        ->assertSessionHasNoErrors()
        ->assertRedirect("/admin/tickets/{$ticket->id}");

    ModuleAssertions::assertAudited($ticket, 'updated');
});

it('gives the second of two saves from the same form a 409 and keeps the first', function (): void {
    $ticket = Ticket::factory()->create();
    ModuleAssertions::actingAsLevelWith(['tickets.view', 'tickets.edit']);

    put("/admin/tickets/{$ticket->id}", ticketInput(['lock_version' => 0]))->assertRedirect();
    put("/admin/tickets/{$ticket->id}", ticketInput(['lock_version' => 0]))->assertStatus(409);

    expect($ticket->fresh()?->lock_version)->toBe(1);
});

it('moves a tiket to the trash and audits it', function (): void {
    $ticket = Ticket::factory()->create();
    ModuleAssertions::actingAsLevelWith(['tickets.view', 'tickets.delete']);

    delete("/admin/tickets/{$ticket->id}")->assertRedirect();

    expect($ticket->fresh()?->trashed())->toBeTrue();
    ModuleAssertions::assertAudited($ticket, 'deleted');
});

it('deletes the selected records in one audit batch', function (): void {
    [$first, $second] = Ticket::factory()->count(2)->create()->all();
    ModuleAssertions::actingAsLevelWith(['tickets.view', 'tickets.delete']);

    delete('/admin/tickets', ['ids' => [$first->id, $second->id]])->assertRedirect();

    expect(Ticket::query()->count())->toBe(0)
        ->and(ImmutableActivity::query()->where('event', 'deleted')->pluck('batch_uuid')->unique()->filter())->toHaveCount(1);
});

it('lets only Super Admin see the trash and restore', function (): void {
    $ticket = Ticket::factory()->create();
    $ticket->delete();
    ModuleAssertions::actingAsLevelWith(['tickets.view', 'tickets.delete']);

    get('/admin/tickets/trash')->assertForbidden();
    post('/admin/tickets/trash/restore', ['ids' => [$ticket->id]])->assertForbidden();

    ModuleAssertions::actingAsSuperAdmin();
    post('/admin/tickets/trash/restore', ['ids' => [$ticket->id]])->assertRedirect();

    expect($ticket->fresh()?->trashed())->toBeFalse();
    ModuleAssertions::assertAudited($ticket, 'restored');
});
